import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
  name: 'timeAgo',
  standalone: true
})
export class TimeAgoPipe implements PipeTransform {

transform(value: string | Date): string {
  if (!value) return '';

  const givenDate = new Date(value);
  const now = new Date();

  if (givenDate > now) return 'In the future';

  // Extract values
  let years = now.getFullYear() - givenDate.getFullYear();
  let months = now.getMonth() - givenDate.getMonth();
  let days = now.getDate() - givenDate.getDate();

  // Fix if day difference is negative
  if (days < 0) {
    const previousMonth = new Date(now.getFullYear(), now.getMonth(), 0).getDate();
    days += previousMonth;
    months--;
  }

  // Fix if month difference is negative
  if (months < 0) {
    months += 12;
    years--;
  }

  // If less than 1 day, compute minutes/hours
  const diffMs = now.getTime() - givenDate.getTime();
  const diffMinutes = Math.floor(diffMs / (1000 * 60));
  const diffHours = Math.floor(diffMs / (1000 * 60 * 60));

  if (diffMinutes < 1) {
    return 'Just now';
  } else if (diffMinutes < 60) {
    return `${diffMinutes} minute${diffMinutes > 1 ? 's' : ''} ago`;
  } else if (diffHours < 24) {
    return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
  }

  // Build output
  let result = [];

  if (years > 0) {
    result.push(`${years} year${years > 1 ? 's' : ''}`);
  }

  if (months > 0) {
    result.push(`${months} month${months > 1 ? 's' : ''}`);
  }

  if (days > 0) {
    result.push(`${days} day${days > 1 ? 's' : ''}`);
  }

  return result.join(' ') + ' ago';
}

}
